1	import { useContext, useState } from "react";
2	import Link from "next/link";
3	import type { EvidenceLevel, Scenario } from "@/src/lib/api";
4	import { EvidenceDot } from "@/src/components/badges";
5	import { Eyebrow, SectionHeading } from "@/src/components/ui/Typography";
6	import { Reveal } from "@/src/components/ui/Reveal";
7	import { MediaContext, MediaImage } from "./MediaImage";
8	import type { HomeData } from "./useHomeData";
9	import { ScenarioFilters, EMPTY_SCENARIO_FILTER, matchesScenario } from "../ScenarioFilters";
10	
11	// Fehlt ein Foto (z. B. G68-CN), zeigen wir eine Typo-Karte im selben Stil statt einer leeren Fläche.
12	function Placeholder({ s }: { s: Scenario }) {
13	  return (
14	    <div className="absolute inset-0 flex flex-col justify-end bg-[radial-gradient(ellipse_at_70%_20%,#1b2a3f_0%,#0a0a0b_75%)] p-6 text-white">
15	      <span className="text-7xl font-extralight leading-none tracking-tight text-white/90">{s.derivative}</span>
16	      <span className="mt-2 text-xs font-semibold uppercase tracking-[0.2em] text-[var(--m-light)]">{s.market}</span>
17	      <span className="absolute inset-x-0 bottom-0 flex h-[3px]" aria-hidden="true">
18	        <span className="flex-1 bg-[var(--m-light)]" /><span className="flex-1 bg-[var(--m-dark)]" /><span className="flex-1 bg-[var(--m-red)]" />
19	      </span>
20	    </div>
21	  );
22	}
23	
24	// Mini-Ampel je Szenario: wie viele Anforderungen sind belegt (grün), schwach (gelb), Annahme (rot).
25	function Lights({ levels }: { levels?: Record<EvidenceLevel, number> }) {
26	  if (!levels) return null;
27	  const rows: [EvidenceLevel, number][] = [["A", levels.A + levels.B], ["C", levels.C], ["D", levels.D]];
28	  return (
29	    <span className="flex items-center gap-3">
30	      {rows.map(([lvl, n]) => (
31	        <span key={lvl} className="flex items-center gap-1.5 tabular-nums"><EvidenceDot level={lvl} size={8} />{n}</span>
32	      ))}
33	    </span>
34	  );
35	}
36	
37	// Raster 3 × 2: jede Karte führt direkt ins Cockpit des Szenarios.
38	// Warum nicht fünf bildschirmhohe Sektionen: Die Szenarien sind Auswahl, nicht Story.
39	export function ScenarioStrip({ data }: { data: HomeData }) {
40	  const media = useContext(MediaContext);
41	  const [filter, setFilter] = useState(EMPTY_SCENARIO_FILTER);
42	  const filtered = data.scenarios.filter(s => matchesScenario(s, filter));
43	  if (data.scenarios.length === 0) return null;
44	  return (
45	    <section id="scenarios" className="bg-[var(--grey-100)] py-24">
46	      <div className="mx-auto max-w-[1400px] px-6 lg:px-10">
47	        <Reveal className="flex flex-wrap items-end justify-between gap-6">
48	          <div>
49	            <Eyebrow>{data.scenarios.length} models and markets</Eyebrow>
50	            <SectionHeading className="mt-3">Pick a model and market.</SectionHeading>
51	          </div>
52	          <p className="max-w-sm text-[var(--grey-500)]">Same pipeline, different data. Each card opens its ranked list.</p>
53	        </Reveal>
54	        <div className="mt-8"><ScenarioFilters scenarios={data.scenarios} value={filter} onChange={setFilter} /></div>
55	        <p role="status" className="mt-4 text-sm text-[var(--grey-500)]">{filtered.length} models and markets</p>
56	        {filtered.length === 0 && <p className="py-8">No models match these filters.</p>}
57	        <div className="mt-6 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
58	          {filtered.map((s, i) => {
59	            const f = data.funnels[s.id];
60	            const src = `/media/scenarios/${s.id}.jpg`;
61	            return (
62	              <Reveal key={s.id} delay={(i % 3) * 100} className="bg-white">
63	                <Link href={`/cockpit?scenario=${s.id}`} className="group relative block h-full">
64	                  <div className="relative aspect-[16/9] overflow-hidden bg-[var(--black)]">
65	                    {media.includes(src) ? (
66	                      <MediaImage src={src} alt={`${s.model_name}, ${s.market}`} sizes="(min-width: 1024px) 33vw, (min-width: 640px) 50vw, 100vw" className="transition-transform duration-[900ms] ease-out group-hover:scale-105" />
67	                    ) : (
68	                      <Placeholder s={s} />
69	                    )}
70	                    <span className="absolute left-4 top-4 bg-black/60 px-2 py-1 text-[10px] font-semibold uppercase tracking-[0.16em] text-white backdrop-blur">
71	                      {s.derivative} · {s.market}
72	                    </span>
