.diagram-img { width: 100%; height: 520px; object-fit: contain; background: var(--white); border: 1px solid var(--hairline); }
/* Seite 3: Pipeline als 7 Kästen, Farbe = wer den Schritt macht (KI / Code / Mensch). */
.pipe { display: grid; grid-template-columns: repeat(7, 1fr); gap: 22px; margin-top: 56px; }
.step { position: relative; border: 2px solid var(--role-code); border-top-width: 8px; background: #f3f4f6; padding: 26px 22px 22px; min-height: 330px; display: flex; flex-direction: column; }
.step.ai { border-color: var(--role-ai); background: var(--blue-50); }
.step.human { border-color: var(--role-human); background: #fdf1e4; }
.step b { font-size: 22px; color: var(--grey-500); font-weight: 600; }
.step h4 { font-size: 34px; font-weight: 500; margin: 6px 0 14px; }
.step p { font-size: 21px; line-height: 1.4; color: var(--ink); }
.step span { margin-top: auto; padding-top: 16px; font-size: 20px; font-weight: 600; color: var(--blue-900); text-transform: uppercase; letter-spacing: .02em; }
.step.human span { color: #9a4f0c; }
.step:not(:last-child)::after { content: "→"; position: absolute; right: -21px; top: 46%; font-size: 26px; color: var(--grey-500); }
/* Challenge-Schleife: gestrichelte Klammer von "Decide" zurück zu "Draft". */
.loop { margin: 0 calc(100% / 7 * 1 + 11px) 0 calc(100% / 7 * 3 + 30px); height: 46px; border: 3px dashed var(--role-human); border-top: none; position: relative; }
.loop span { position: absolute; left: 50%; bottom: -40px; transform: translateX(-50%); white-space: nowrap; font-size: 22px; color: #9a4f0c; }

