// Renders every slide of a deck HTML file as slide-<n>.png (1920x1080).
const { chromium } = require("../shots/node_modules/playwright-core");
const path = require("path");
const [html, outDir] = process.argv.slice(2);
const EXE = process.env.LOCALAPPDATA + "\\ms-playwright\\chromium-1248\\chrome-win64\\chrome.exe";
(async () => {
  const b = await chromium.launch({ executablePath: EXE });
  const p = await b.newPage({ viewport: { width: 1920, height: 1080 } });
  await p.goto("file:///" + html.replace(/\\/g, "/"), { waitUntil: "networkidle" });
  await p.addStyleTag({ content: ".slide{zoom:1 !important}" });
  await p.waitForTimeout(800);
  const slides = p.locator("section.slide");
  const n = await slides.count();
  for (let i = 0; i < n; i++) await slides.nth(i).screenshot({ path: path.join(outDir, `slide-${i + 1}.png`) });
  await b.close();
  console.log("rendered", n);
})();

